import math

def omega(num):
    if num == 0:
        return 0
    count = 0
    n = abs(num)
    d = 2
    temp = n
    while d * d <= temp:
        if temp % d == 0:
            count += 1
            while temp % d == 0:
                temp //= d
        d += 1
    if temp > 1:
        count += 1
    return count

n_values = [17, 18, 19, 20, 21]
results = {}

for n in n_values:
    try:
        factorial_n = math.factorial(n)

        if factorial_n % 2023 != 0:
            results[n] = "Not an integer"
            continue

        N = factorial_n // 2023
        k = omega(N)
        results[n] = k
    except Exception as e:
        results[n] = f"Error: {e}"

print(results)

def factorize(n):
    factors = {}
    d = 2
    temp = n
    while d * d <= temp:
        while temp % d == 0:
            factors[d] = factors.get(d, 0) + 1
            temp //= d
        d += 1
    if temp > 1:
        factors[temp] = factors.get(temp, 0) + 1
    return factors

print(f"Factorization of 2023: {factorize(2023)}")

def prime_count(n):
    if n < 2:
        return 0
    count = 0
    is_prime = [True] * (n + 1)
    is_prime[0] = is_prime[1] = False
    for p in range(2, n + 1):
        if is_prime[p]:
            count += 1
            for i in range(p * p, n + 1, p):
                is_prime[i] = False
    return count

print(f"pi(10) = {prime_count(10)}")
print(f"pi(12) = {prime_count(12)}")
print(f"pi(13) = {prime_count(13)}")
print(f"pi(17) = {prime_count(17)}")

